  const f = () => ({ 'Last 7 days': .24, 'Last 30 days': 1, 'Last 90 days': 2.9, 'This year': 9.4 })[st.date] * (st.location === 'All locations' ? 1 : st.location === 'Westminster' ? .62 : .38) * (st.clinician === 'All clinicians' ? 1 : .14) * (st.service === 'All services' ? 1 : .2) * (st.ptype === 'All patients' ? 1 : st.ptype === 'New patients' ? .32 : .68)
    * (st.journey === 'All journeys' ? 1 : st.journey === 'Patient booking' ? .81 : .19) * (st.ltype === 'All leads' ? 1 : st.ltype === 'Patient' ? .81 : .19) * (st.owner === 'All owners' ? 1 : .3) * (st.source === 'All sources' ? 1 : .25) * (st.form === 'All forms' ? 1 : .2) * (st.staff === 'All staff' ? 1 : .4) * (st.dtype === 'All types' ? 1 : .25);
  const N = v => Math.max(0, Math.round(v * f())); const nf = v => N(v).toLocaleString('en-GB');
