  const card = (t, sub, body, opts = {}) => `<section class="card an-card ${opts.cls || ''}" ${opts.id ? `id="${opts.id}"` : ''}><div class="an-card-h"><div><h2>${t}</h2>${sub ? `<p>${sub}</p>` : ''}</div>${opts.action || ''}</div><div class="an-card-b">${body}</div>${opts.foot ? `<p class="an-foot ${opts.footTone || ''}">${opts.foot}</p>` : ''}</section>`;
